async function importProducts() {
  console.log(`🗑  Suppression des anciens produits eBay...`)
  const { error: delError } = await supabase.from('products').delete().eq('source', 'ebay')
  if (delError) console.log('Note:', delError.message)
  else console.log('✓ Anciens produits supprimés')

  const BATCH = 50
  let success = 0

  for (let i = 0; i < products.length; i += BATCH) {
    const batch = products.slice(i, i + BATCH)
    const { error } = await supabase.from('products').insert(batch)
    if (error) console.error(`Batch ${Math.floor(i/BATCH)+1} error:`, error.message)
    else {
      success += batch.length
      process.stdout.write(`\r✓ ${success}/${products.length} importés`)
    }
  }

  console.log(`\n\n✅ Terminé! ${success} produits importés dans Supabase.`)
  console.log('⚠️  Les images seront ajoutées séparément via le script images.')
}

importProducts().catch(console.error)
